package bcc

import (
	"errors"
	"net/url"
	"strings"
	"testing"
)

// These expected signatures are independently published in BCC's MAC TRTYPE
// examples, not generated by the implementation under test:
// https://documenter.getpostman.com/view/23274245/2s7YYo95nr
func TestPublishedRequestSignatures(t *testing.T) {
	for _, test := range []struct {
		kind TransactionType
		want string
	}{
		{Purchase, "9B1C58714CFF6E4BCC6E97B4D503275838F4ED68"},
		{Refund, "0D8ABFC1215135BD51AB27C10E2CD621C5AF1432"},
		{Reversal, "36D5B6DC398518414F7BA5B1D8177B79A13E1BC8"},
		{CreateToken, "2349EE6CBA1C9E29DDC7B7CEDD9ED45352590E9B"},
		{DeleteToken, "7D96110F1E70C55455D588132BDA5684B64BA49C"},
		{StatusQuery, "7C0D8BF3F6C7DCB0AA35E88F045292E176184B5E"},
		{RecurringCharge, "52A307DC1BF1D3CCCD819402279371615DAABDD4"},
	} {
		t.Run(string(test.kind), func(t *testing.T) {
			got, err := SignRequest(test.kind, publishedFields(test.kind), publicTestKey)
			if err != nil || got != test.want {
				t.Fatalf("signature = %q, %v; want published vector %q", got, err, test.want)
			}
		})
	}
}

func publishedFields(kind TransactionType) url.Values {
	return url.Values{
		"AMOUNT": {"350.00"}, "ORG_AMOUNT": {"350.00"}, "CURRENCY": {"398"}, "ORDER": {"3558714461568"},
		"MERCHANT": {"merchantname"}, "TERMINAL": {"88888881"}, "MERCH_GMT": {"0"},
		"TIMESTAMP": {"20200224073921"}, "TRTYPE": {string(kind)}, "NONCE": {"F2B2DD7E603A7AAF5E1BC35DEE1F6C9A"},
		"RRN": {"821185120045"}, "INT_REF": {"9C2176F638FDC05C"},
		"MERCH_TOKEN_ID": {"0CBB126352804BD46EE0E0019EBCDC94"}, "RECUR_REF": {"925885667408"},
	}
}

func TestRequestSigningRejectsAmbiguityAndChangesWithSignedData(t *testing.T) {
	fields := publishedFields(Purchase)
	original, _ := SignRequest(Purchase, fields, publicTestKey)
	fields.Set("AMOUNT", "350.01")
	tampered, err := SignRequest(Purchase, fields, publicTestKey)
	if err != nil || original == tampered {
		t.Fatal("changing the signed amount must change the signature")
	}
	// DESC is not in BCC's prescribed field list; do not silently sign extras.
	fields.Set("DESC", "Описание покупки")
	withDescription, err := SignRequest(Purchase, fields, publicTestKey)
	if err != nil || withDescription != tampered {
		t.Fatal("the documented MAC list must not grow with extra fields")
	}
	for _, mutate := range []func(url.Values){
		func(v url.Values) { v.Del("ORDER") },
		func(v url.Values) { v.Set("ORDER", "") },
		func(v url.Values) { v.Add("ORDER", "different") },
		func(v url.Values) { v.Set("DESC", "first description"); v.Add("DESC", "second description") },
		func(v url.Values) { v.Set("TRTYPE", "14") },
		func(v url.Values) { v.Set("MERCHANT", "тест") },
		func(v url.Values) { v.Set("MERCHANT", "merchant\nname") },
	} {
		bad := publishedFields(Purchase)
		mutate(bad)
		if _, err := SignRequest(Purchase, bad, publicTestKey); !errors.Is(err, ErrInvalidRequest) {
			t.Fatalf("ambiguous or unsupported signed input accepted: %v", err)
		}
	}
	for _, key := range []string{"", "not a hex key", "690B", strings.Repeat("AA", 65)} {
		if _, err := SignRequest(Purchase, publishedFields(Purchase), key); !errors.Is(err, ErrInvalidKey) {
			t.Fatalf("invalid key accepted: %v", err)
		}
	}
	if _, err := SignRequest(ConnectionCheck, publishedFields(ConnectionCheck), publicTestKey); !errors.Is(err, ErrUnsupportedTransaction) {
		t.Fatalf("unsigned connection check must not get an invented MAC list: %v", err)
	}
}
